<?php require_once __DIR__.'/../includes/functions.php';need_role(['admin_utama']);if($_SERVER['REQUEST_METHOD']!=='POST')go('/laporwarga/admin-utama/penugasan.php');check_csrf();$rid=(int)($_POST['id_laporan']??0);$uid=(int)($_POST['id_petugas']??0);$q=db()->prepare("SELECT id_user FROM users WHERE id_user=? AND role='petugas' AND status_akun=1");$q->execute([$uid]);if(!$q->fetch()){flash('error','Pilih petugas aktif yang valid.');go('/laporwarga/admin-utama/penugasan.php');}$q=db()->prepare('SELECT id_pelapor,nomor_laporan FROM reports WHERE id_laporan=?');$q->execute([$rid]);$r=$q->fetch();if(!$r){flash('error','Laporan tidak ditemukan.');go('/laporwarga/admin-utama/penugasan.php');}db()->prepare('UPDATE reports SET id_petugas=?,updated_at=NOW() WHERE id_laporan=?')->execute([$uid,$rid]);notify($uid,'Penugasan laporan baru','Anda mendapat tugas untuk laporan '.$r['nomor_laporan'],'/laporwarga/petugas/daftar_laporan.php');notify((int)$r['id_pelapor'],'Laporan ditugaskan','Laporan '.$r['nomor_laporan'].' telah ditugaskan kepada petugas.','/laporwarga/masyarakat/daftar_laporan.php');log_activity('penugasan',$r['nomor_laporan'].' kepada petugas '.$uid);flash('success','Penugasan berhasil disimpan.');go('/laporwarga/admin-utama/penugasan.php');